pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        // Restrict to admissible domain: target is not the contract itself, amount within balance
        vm.assume(target != address(c));
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);

        // Fund the contract so sendMoney has enough balance
        vm.deal(address(c), amount);

        // Execute sendMoney as the owner (msg.sender is the owner by default in setUp)
        c.sendMoney(target, amount);

        // After sendMoney completes (whether it reverted or not),
        // the owner calling withdraw should succeed on the reference C.
        // On the buggy version, the inverted onlyOwner prevents the owner from withdrawing.
        bool withdrawSucceeded;
        try c.withdraw(1) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // The reference C satisfies: withdraw always succeeds for the owner after sendMoney.
        assertTrue(withdrawSucceeded);
    }
}

