pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != c.owner());
        vm.assume(amount > 0 && amount <= address(this).balance);

        // Fund the contract via fallback so it has balance
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 balanceBeforeOwner = c.owner().balance;
        uint256 balanceBeforeContract = address(c).balance;
        uint256 sumBefore = balanceBeforeOwner + balanceBeforeContract;

        // Owner calls withdraw
        vm.prank(c.owner());
        c.withdraw(amount);

        uint256 balanceAfterOwner = c.owner().balance;
        uint256 balanceAfterContract = address(c).balance;
        uint256 sumAfter = balanceAfterOwner + balanceAfterContract;

        // For the correct contract, sumAfter == sumBefore (funds just moved).
        // For the buggy version, sumAfter > sumBefore because no transfer occurred,
        // yet the owner's balance didn't increase (so sum unchanged? Actually:
        // buggy withdraw does nothing, so contract balance unchanged, owner balance unchanged => sum unchanged.
        // That would not distinguish. We need a property that the bug breaks.
        // Instead: after withdraw, the owner's balance must strictly increase by amount.
        // Buggy version: no increase, so owner balance unchanged.
        assertTrue(balanceAfterOwner == balanceBeforeOwner + amount);
    }
}

